return {["fb30_01"]={["down"]=[[fb30_03]],["dsc"]=[[从这里往北可到大理国北。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_01]],["item1"]=[[bfitem1]],["name"]=[[大理国北]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb30_02"]={["dsc"]=[[从这里往西可到大理国西。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_02]],["name"]=[[大理国西]],["permission"]=2,["right"]=[[fb30_03]],["stepMusic"]=[[jiaobu]]},["fb30_03"]={["down"]=[[fb30_07]],["dsc"]=[[阳苜咩城，或简称苜咩城，是大理国的都城。历经陈氏“长大和国”、赵氏“大天兴国”、杨氏“大义宁国”诸代而至当今的段氏的“大理国”，均以此城为都。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_03]],["item1"]=[[fb30item7]],["left"]=[[fb30_02]],["name"]=[[北门]],["permission"]=1,["right"]=[[fb30_04]],["role1"]=[[fb30r03_1]],["role2"]=[[fb30r03_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_01]]},["fb30_04"]={["dsc"]=[[从这里往东可到大理国东。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_04]],["left"]=[[fb30_03]],["name"]=[[大理国东]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb30_05"]={["down"]=[[fb30_08]],["dsc"]=[[这里是法堂，若是拜佛可来此地，据说这里的菩萨灵验得很。]],["id"]=[[fb30_05]],["item1"]=[[fb30item105]],["name"]=[[法堂]],["permission"]=2,["role1"]=[[fb30r05_100]],["stepMusic"]=[[jiaobu]]},["fb30_06"]={["dsc"]=[[从这里往西可到大理王府。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_06]],["left"]=[[fb30_61]],["name"]=[[大理王府]],["permission"]=1,["right"]=[[fb30_07]],["stepMusic"]=[[jiaobu]]},["fb30_07"]={["down"]=[[fb30_17]],["dsc"]=[[这是大理城的牌坊，正中一个牌坊上写着四个金色大字:圣道广慈。西边是皇宫，东边是一条青石大道，由于大理国主体民如子，虽皇宫近在咫尺，但金吾不禁，百姓往来如潮。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_07]],["left"]=[[fb30_06]],["name"]=[[太和街口]],["permission"]=1,["right"]=[[fb30_08]],["role1"]=[[fb30r07_1]],["role2"]=[[fb30r07_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_03]]},["fb30_08"]={["down"]=[[fb30_10]],["dsc"]=[[你正站在一座豪华的府门前，门前有两只极大的石狮子，门上高悬一块横匾，上书「定安王府」四个金字。门口站着两排侍卫，身着锦衣，手执钢刀，气宇轩昂。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_08]],["left"]=[[fb30_07]],["name"]=[[定安府]],["permission"]=2,["role1"]=[[fb30r08_1]],["role2"]=[[fb30r08_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_05]]},["fb30_09"]={["dsc"]=[[小院内的厢房，给客人们休息的地方，东边可达小院。]],["id"]=[[fb30_09]],["name"]=[[厢房]],["permission"]=2,["right"]=[[fb30_10]],["role1"]=[[fb30r09_1]],["stepMusic"]=[[jiaobu]]},["fb30_10"]={["down"]=[[fb30_12]],["dsc"]=[[王府内的小院，可通厢房，伙房和库房。]],["id"]=[[fb30_10]],["left"]=[[fb30_09]],["name"]=[[小院]],["permission"]=2,["right"]=[[fb30_11]],["rightDown"]=[[fb30_13]],["role1"]=[[fb30r10_1]],["role2"]=[[fb30r10_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_08]]},["fb30_11"]={["dsc"]=[[小院内的厢房，给客人们休息的地方，西边可达小院。]],["id"]=[[fb30_11]],["left"]=[[fb30_10]],["name"]=[[厢房]],["permission"]=2,["role1"]=[[fb30r11_1]],["stepMusic"]=[[jiaobu]]},["fb30_12"]={["dsc"]=[[王府内做饭的地方，北面就是王府。]],["id"]=[[fb30_12]],["name"]=[[伙房]],["permission"]=2,["role1"]=[[fb30r12_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_10]]},["fb30_13"]={["dsc"]=[[王府内存放物事的地方，通小院。]],["id"]=[[fb30_13]],["item1"]=[[fb30item22]],["leftUp"]=[[fb30_10]],["name"]=[[库房]],["permission"]=2,["role1"]=[[fb30r13_1]],["stepMusic"]=[[jiaobu]]},["fb30_14"]={["down"]=[[fb30_18]],["dsc"]=[[这是一家老字号的估衣庄，里面摆满了各式各样的衣物。绸、绢、丝、布、皮袄、大红斗蓬、葱黄绫子棉裙、水绿色棉袄，秋香色团花…不一而足。]],["id"]=[[fb30_14]],["name"]=[[薛记成衣铺]],["permission"]=2,["role1"]=[[fb30r14_1]],["role2"]=[[fb30r14_2]],["stepMusic"]=[[jiaobu]]},["fb30_15"]={["dsc"]=[[在这里你能享受到城内少有的清净。池内鱼虾龟虫倒也养了不少，在这四季如春的气候下，荷花睡莲无比妖娆。]],["id"]=[[fb30_15]],["item1"]=[[fb30item12]],["name"]=[[清池]],["permission"]=2,["right"]=[[fb30_16]],["role1"]=[[fb30r15_1]],["role2"]=[[fb30r15_100]],["stepMusic"]=[[jiaobu]]},["fb30_16"]={["dsc"]=[[这里便是蛇骨塔。相传洱海有妖蛇名“薄劫”，其尾塞海口，洪水泛滥，有勇士段赤城只身入洱海与妖蛇同归于尽。后人建塔以镇水势，用蛇骨灰塔，水势自息。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_16]],["item1"]=[[fb30item10]],["item2"]=[[fb30item11]],["left"]=[[fb30_15]],["name"]=[[蛇骨塔]],["permission"]=1,["right"]=[[fb30_17]],["stepMusic"]=[[jiaobu]]},["fb30_17"]={["down"]=[[fb30_20]],["dsc"]=[[太和街连贯阳苜咩城南北门，延伸三里，是城内主要街道。街面是由碗口大的彩色石块铺成，青兰紫绿，煞是好看。街上行人络绎不绝。大道两边遍植松柏，满目苍翠。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_17]],["item1"]=[[fb30item9]],["left"]=[[fb30_16]],["name"]=[[太和街口]],["permission"]=1,["right"]=[[fb30_18]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_07]]},["fb30_18"]={["down"]=[[fb30_22]],["dsc"]=[[太和街连贯阳苜咩城南北门，延伸三里，是城内主要街道。街面是由碗口大的彩色石块铺成，青兰紫绿，煞是好看。北面是薛记成衣铺，南面是药铺。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_18]],["left"]=[[fb30_17]],["name"]=[[太和东街]],["permission"]=2,["right"]=[[fb30_19]],["role1"]=[[fb30r18_1]],["role2"]=[[fb30r18_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_14]]},["fb30_19"]={["dsc"]=[[大理地段有一山石以其天然的花纹而闻名天下，那便是大名鼎鼎的大理石。用大理石中的水墨花石制作的画屏，其奇妙程度，使人叹而观止。店里一位老人正在指导学徒。]],["id"]=[[fb30_19]],["left"]=[[fb30_18]],["name"]=[[石铺]],["permission"]=2,["role1"]=[[fb30r19_1]],["role2"]=[[fb30r19_2]],["role3"]=[[fb30r19_100]],["stepMusic"]=[[jiaobu]]},["fb30_20"]={["down"]=[[fb30_26]],["dsc"]=[[这里就是阳苜咩城的中心，彩色石块铺成的大道向四方伸延。熙熙攘攘的人群中也少不了几个跑江湖之人，一些在中原闻所未闻的事物令一些刚入江湖之人兴奋不已。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_20]],["name"]=[[中心广场]],["permission"]=2,["right"]=[[fb30_21]],["role1"]=[[fb30r20_1]],["role2"]=[[fb30r20_100]],["role3"]=[[fb30r20_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_17]]},["fb30_21"]={["dsc"]=[[这是大理城内最大的酒楼，楼下卖些大理的小吃，过往行人常常买来作路菜。楼上是雅座。]],["id"]=[[fb30_21]],["left"]=[[fb30_20]],["name"]=[[太和居]],["permission"]=2,["role1"]=[[fb30r21_1]],["role2"]=[[fb30r21_2]],["role3"]=[[fb30r21_3]],["role4"]=[[fb30r21_4]],["stepMusic"]=[[jiaobu]]},["fb30_22"]={["dsc"]=[[这是一家神秘的药铺，座落在大和街和市中心的交界处，从药柜上的几百个小抽屉里散发出来的一股浓浓的药味，让你几欲窒息。据说这家店铺有一种很神秘的药物。]],["id"]=[[fb30_22]],["item1"]=[[lylitem1]],["name"]=[[药铺]],["permission"]=2,["role1"]=[[fb30r22_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_18]]},["fb30_23"]={["down"]=[[fb30_25]],["dsc"]=[[土司府是当地傣族世袭土司刀氏的衙门，一座古老的砖木建筑物，门庭居高临下，庄严坚实，门前是宽广的石阶，屋共三台，占地约八百亩，分作正厅，议事厅，后厅，厢房。]],["id"]=[[fb30_23]],["name"]=[[土司府]],["permission"]=2,["role1"]=[[fb30r23_1]],["role2"]=[[fb30r23_2]],["stepMusic"]=[[jiaobu]]},["fb30_24"]={["down"]=[[fb30_27]],["dsc"]=[[摆夷文字有悠久的历史…摆夷文一般是由左向右竖行书写，用毛笔或竹签写在纸或白布上。这儿就有一摆夷学者为人代写书信，告文，契约等等。]],["id"]=[[fb30_24]],["name"]=[[摆夷字馆]],["permission"]=2,["role1"]=[[fb30r24_1]],["stepMusic"]=[[jiaobu]]},["fb30_25"]={["down"]=[[fb30_29]],["dsc"]=[[这是一条青石板路，两边种了不少柏树，显得庄严肃穆。南面是大理城的守军驻地，隐隐可以听到兵士们操练的号子声，向北是土司府，是当今皇太妃刀氏一族的世袭衙门。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_25]],["name"]=[[大和街]],["permission"]=2,["right"]=[[fb30_26]],["role1"]=[[fb30r25_1]],["role2"]=[[fb30r25_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_23]]},["fb30_26"]={["down"]=[[fb30_31]],["dsc"]=[[这是大理城内的主要商贸场所。形形色色的叫卖声在耳边此起彼伏，连绵不绝。路上车水马龙，各色行人摩肩接踵，热闹非凡。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_26]],["left"]=[[fb30_25]],["name"]=[[十字路口]],["permission"]=2,["right"]=[[fb30_27]],["role1"]=[[fb30r26_1]],["role2"]=[[fb30r26_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_20]]},["fb30_27"]={["down"]=[[fb30_30]],["dsc"]=[[大道旁店铺林立，长街故朴，屋舍鳞次栉比，道上人来车往，一片太平热闹景象。路口种了两棵大菩提树，树下有一个大洞。一踏入巷中，阵阵茶花香气扑鼻而来。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_27]],["left"]=[[fb30_26]],["name"]=[[大和街]],["permission"]=2,["role1"]=[[fb30r27_1]],["role2"]=[[fb30r27_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_24]]},["fb30_28"]={["dsc"]=[[这是军营边上的马厩，常年供应新鲜草料。据说此地民风淳朴，客人只要带马来，马夫们就会把马牵到马厩好生照看，将它们喂饱饮足，再洗刷得干乾净净。]],["id"]=[[fb30_28]],["item1"]=[[fb30item102]],["item2"]=[[fb30item103]],["name"]=[[马厩]],["permission"]=2,["right"]=[[fb30_29]],["role1"]=[[fb30r28_1]],["stepMusic"]=[[jiaobu]]},["fb30_29"]={["dsc"]=[[大理国虽小，却重视精兵良将。然屈人必先屈志，兵戈乃下下之策，段氏大理先与北邻宋朝修和，再以姻亲拉拢当地人，多年无战事。]],["id"]=[[fb30_29]],["left"]=[[fb30_28]],["name"]=[[兵营]],["permission"]=2,["role1"]=[[fb30r29_1]],["role2"]=[[fb30r29_2]],["role3"]=[[fb30r29_3]],["role4"]=[[fb30r29_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_25]]},["fb30_30"]={["dsc"]=[[摆夷是大理第一大族，摆夷民居以石块垒成，别具风格。朝花节那天，家家户户都把盆栽花木摆在门口，摆搭成一座座的“花山”，招引四野乡村的人来观花街。]],["id"]=[[fb30_30]],["name"]=[[摆夷民居]],["permission"]=2,["role1"]=[[fb30r28_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_27]]},["fb30_31"]={["down"]=[[fb30_33]],["dsc"]=[[此间是大理国都大理城的南门，大理城实名阳苜咩城，南诏于初建来，经历代而至当今的段氏的“大理国”，皆以此城为都。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_31]],["name"]=[[南门]],["permission"]=2,["right"]=[[fb30_32]],["role1"]=[[fb30r31_1]],["role2"]=[[fb30r31_100]],["role3"]=[[fb30r31_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_26]]},["fb30_32"]={["dsc"]=[[从这里往东可到大理国东。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_32]],["left"]=[[fb30_31]],["name"]=[[大理国东]],["permission"]=2,["role1"]=[[fb30r32_100]],["role2"]=[[fb30r32_101]],["stepMusic"]=[[jiaobu]]},["fb30_33"]={["dsc"]=[[从这里往南可到大理国南。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_33]],["name"]=[[大理国南]],["permission"]=2,["role1"]=[[fb30r33_100]],["role2"]=[[fb30r33_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_31]]},["fb30_34"]={["dsc"]=[[大山石又名寿山石，你眼前的这块与其他大山石有所不同，其质纯洁通灵，月光的照耀下，闪着荧光，如同黑暗中的萤火虫一般，照亮了周围一片土地…]],["id"]=[[fb30_34]],["item1"]=[[fb30item17]],["name"]=[[大山石]],["permission"]=2,["rightDown"]=[[fb30_39]],["stepMusic"]=[[jiaobu]]},["fb30_35"]={["dsc"]=[[这是王爷的睡房，墙壁上挂着几柄宝剑，书桌上摆放着纸笔，古香古色。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb30_35]],["item1"]=[[fb30item23]],["name"]=[[睡房]],["permission"]=2,["right"]=[[fb30_36]],["rightDown"]=[[fb30_40]],["stepMusic"]=[[jiaobu]]},["fb30_36"]={["dsc"]=[[这是大理国镇南王的书房，靠窗放着一个大木桌桌上放着不少书，靠墙的地方还有一个书架，镇南王经常在这里看书。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb30_36]],["item1"]=[[fb30item19]],["item2"]=[[fb30item19]],["item3"]=[[fb30item23]],["left"]=[[fb30_35]],["name"]=[[书房]],["permission"]=2,["role1"]=[[fb30r36_1]],["stepMusic"]=[[jiaobu]]},["fb30_37"]={["dsc"]=[[这是大理国镇南王的书房，靠窗放着一个大木桌桌上放着不少书，靠墙的地方还有一个书架，镇南王经常在这里看书。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb30_37]],["item1"]=[[fb30item19]],["item2"]=[[fb30item19]],["item3"]=[[fb30item23]],["leftDown"]=[[fb30_40]],["name"]=[[书房]],["permission"]=2,["role1"]=[[fb30r37_1]],["stepMusic"]=[[jiaobu]]},["fb30_38"]={["down"]=[[fb30_41]],["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。你站在茶花园的最高处，低头看去，满园春色，尽在目下。西望亭台楼阁，错落有秩。]],["id"]=[[fb30_38]],["item1"]=[[fb30item18]],["item2"]=[[fb30item18]],["name"]=[[茶花院]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb30_39"]={["down"]=[[fb30_44]],["dsc"]=[[这里是镇南王府的内厅。整个大厅十分宽阔。虽说是王府，但摆设很简单，正中间有两张太师椅，边上摆满了各种各样的山茶花。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb30_39]],["leftUp"]=[[fb30_34]],["name"]=[[厅房]],["permission"]=2,["right"]=[[fb30_40]],["role1"]=[[fb30r39_1]],["stepMusic"]=[[jiaobu]]},["fb30_40"]={["dsc"]=[[这里是镇南王府的内堂。十分宽阔明亮。正面墙上挂着一幅水墨画，两边各有一个窗子，透过窗户可以看见外面的青山绿水。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb30_40]],["left"]=[[fb30_39]],["leftUp"]=[[fb30_35]],["name"]=[[厢房]],["permission"]=2,["rightUp"]=[[fb30_37]],["role1"]=[[fb30r40_1]],["stepMusic"]=[[jiaobu]]},["fb30_41"]={["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。你站在茶花园中，北面是一片波光涟滟的湖面。靠岸的柳树下，有几盆茶花，娇艳照人，在满园烂漫的茶花围中，仍骄然出群。]],["id"]=[[fb30_41]],["item1"]=[[fb30item3]],["item2"]=[[fb30item18]],["name"]=[[茶花院]],["permission"]=2,["right"]=[[fb30_42]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_38]]},["fb30_42"]={["down"]=[[fb30_46]],["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。你站在茶花园中，北面是一座小山，山上栽满了常青乔木。地上草地，密密层层的。东面有一个小小庭院，西边望去仍是一片万紫千红。]],["id"]=[[fb30_42]],["item1"]=[[fb30item18]],["item2"]=[[fb30item18]],["left"]=[[fb30_41]],["name"]=[[茶花院]],["permission"]=2,["right"]=[[fb30_43]],["stepMusic"]=[[jiaobu]]},["fb30_43"]={["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。你站在茶花园后门口，对着满园春色，不禁大喜过望。]],["id"]=[[fb30_43]],["item1"]=[[fb30item18]],["item2"]=[[fb30item18]],["left"]=[[fb30_42]],["name"]=[[茶花院]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb30_44"]={["dsc"]=[[这是镇南王府的甬道。两边是密密的树林，风吹得树叶沙沙声响石砌的甬道路面两侧，是如茵的绿草，点缀着一星半点的小花，周围十分安静。]],["id"]=[[fb30_44]],["name"]=[[甬路]],["permission"]=2,["right"]=[[fb30_45]],["rightDown"]=[[fb30_48]],["role1"]=[[fb30r44_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_39]]},["fb30_45"]={["dsc"]=[[这是镇南王府的甬道。两边是密密的参天乔木，天光透过树叶，在地上洒下星星斑点。甬道路面两侧，如茵的绿草，点缀着一星半点的小花，周围十分安静，偶尔虫鸣悠扬。]],["id"]=[[fb30_45]],["left"]=[[fb30_44]],["name"]=[[甬路]],["permission"]=2,["role1"]=[[fb30r45_1]],["stepMusic"]=[[jiaobu]]},["fb30_46"]={["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。你站在茶花园中，发现几朵娇嫩欲滴的茶花，你不禁多看了两眼。西面是一个小湖，湖面碧绿如玉，暖风吹来，曛曛入醉。]],["id"]=[[fb30_46]],["item1"]=[[fb30item18]],["item2"]=[[fb30item18]],["leftDown"]=[[fb30_49]],["name"]=[[茶花院]],["permission"]=1,["rightDown"]=[[fb30_50]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_42]]},["fb30_47"]={["dsc"]=[[这里便是承光壁了，逢满月之时，月光照在这石壁上，会折射出不同的景象，美轮美奂，令人陶醉。]],["id"]=[[fb30_47]],["item1"]=[[fb30item16]],["name"]=[[承光壁]],["permission"]=2,["right"]=[[fb30_48]],["stepMusic"]=[[jiaobu]]},["fb30_48"]={["down"]=[[fb30_52]],["dsc"]=[[这里是王府大殿，再往北就是厢房，厅房了，若是想赏花可往东走。]],["id"]=[[fb30_48]],["left"]=[[fb30_47]],["leftUp"]=[[fb30_44]],["name"]=[[大殿]],["permission"]=2,["role1"]=[[fb30r48_1]],["stepMusic"]=[[jiaobu]]},["fb30_49"]={["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。你正走在茶花园中，层层密密的都是争奇斗妍的茶花。靠南岸边一溜的盆栽的茶花，微风从水面吹来，摇曳婆娑。]],["id"]=[[fb30_49]],["item1"]=[[fb30item8]],["name"]=[[茶花院]],["permission"]=1,["rightDown"]=[[fb30_55]],["rightUp"]=[[fb30_46]],["role1"]=[[fb30r49_1]],["role2"]=[[fb30r49_2]],["role3"]=[[fb30r49_3]],["role4"]=[[fb30r49_4]],["stepMusic"]=[[jiaobu]]},["fb30_50"]={["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。靠岸的柳树下，有几盆茶花，娇艳照人，在满园烂漫的茶花围中，仍骄然出群。]],["id"]=[[fb30_50]],["item1"]=[[fb30item18]],["item2"]=[[fb30item18]],["leftDown"]=[[fb30_55]],["leftUp"]=[[fb30_46]],["name"]=[[茶花院]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb30_51"]={["dsc"]=[[有欲观窍，无欲观妙，观妙亭以此为名提醒着世人，不要拘泥于事物的表象。]],["id"]=[[fb30_51]],["name"]=[[观妙亭]],["permission"]=2,["right"]=[[fb30_52]],["stepMusic"]=[[jiaobu]]},["fb30_52"]={["down"]=[[fb30_59]],["dsc"]=[[青石板的路一直延伸，似乎前方就是茶花园了。]],["id"]=[[fb30_52]],["left"]=[[fb30_51]],["name"]=[[石板路]],["permission"]=1,["right"]=[[fb30_53]],["role1"]=[[fb30r52_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_48]]},["fb30_53"]={["dsc"]=[[这喷水池设计之精妙，技巧之高超，当世无双。]],["id"]=[[fb30_53]],["item1"]=[[fb30item21]],["left"]=[[fb30_52]],["name"]=[[喷水池]],["permission"]=1,["right"]=[[fb30_54]],["stepMusic"]=[[jiaobu]]},["fb30_54"]={["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。你站在茶花园口，对着满园春色，不禁大喜过望。东边就进园了，北边是一个库房。南边是一栋厢房。]],["id"]=[[fb30_54]],["left"]=[[fb30_53]],["name"]=[[茶花园入口]],["permission"]=1,["right"]=[[fb30_55]],["stepMusic"]=[[jiaobu]]},["fb30_55"]={["dsc"]=[[大理茶花冠绝天下，镇南王府的茶花自然更非凡品。你站在茶花园中，看万紫千红，争奇斗妍，心胸大爽。靠东一座小石凳，凳后柳树成行，拖曳水面，把湖面点成一个个涟漪。]],["id"]=[[fb30_55]],["left"]=[[fb30_54]],["leftUp"]=[[fb30_49]],["name"]=[[茶花园]],["permission"]=1,["rightUp"]=[[fb30_50]],["role1"]=[[fb30r55_1]],["stepMusic"]=[[jiaobu]]},["fb30_56"]={["down"]=[[fb30_58]],["dsc"]=[[这里是大理国司马堂。大理东北强宋，西北吐蕃，历年来边疆宁靖，皆司马劳顿之功。盖吐蕃垂涎大理已久，每每强辞胁迫，大理不得不重兵于西北。]],["id"]=[[fb30_56]],["name"]=[[司马堂]],["permission"]=2,["role1"]=[[fb30r56_1]],["stepMusic"]=[[jiaobu]]},["fb30_57"]={["dsc"]=[[这里是大理国司空堂。堂内无余物，四壁却堆满了书籍。想来主人爱书如命，即便工余亦手不释卷。]],["id"]=[[fb30_57]],["name"]=[[司空堂]],["permission"]=2,["right"]=[[fb30_58]],["role1"]=[[fb30r57_1]],["stepMusic"]=[[jiaobu]]},["fb30_58"]={["down"]=[[fb30_62]],["dsc"]=[[总理处是镇南王皇太弟总理国务之处，满桌的奏章整理得井井有条。四周摆了很多茶花，争奇斗艳。茶花是大理国花，看来主人对它也是钟爱有加。]],["id"]=[[fb30_58]],["left"]=[[fb30_57]],["name"]=[[府衙前厅]],["permission"]=2,["right"]=[[fb30_59]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_56]]},["fb30_59"]={["dsc"]=[[从这里西边可至府衙前厅，北可至大殿。]],["id"]=[[fb30_59]],["left"]=[[fb30_58]],["name"]=[[前院]],["permission"]=1,["right"]=[[fb30_60]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_52]]},["fb30_60"]={["dsc"]=[[你正站在一座豪华的府门前，门前有两只极大的石狮子，门上高悬一块横匾，上书「镇南王府」四个金字。门口站着两排侍卫，身着锦衣，手执钢刀，气宇轩昂。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_60]],["left"]=[[fb30_59]],["name"]=[[王府大门]],["permission"]=1,["right"]=[[fb30_61]],["role1"]=[[fb30r60_1]],["role2"]=[[fb30r60_2]],["stepMusic"]=[[jiaobu]]},["fb30_61"]={["dsc"]=[[从这里出去可以到大理内城。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb30_61]],["left"]=[[fb30_60]],["name"]=[[大理城]],["permission"]=1,["right"]=[[fb30_06]],["stepMusic"]=[[jiaobu]]},["fb30_62"]={["dsc"]=[[这里是大理国司徒堂。大理君臣勤政爱民，三公劳作自不带言。堂内无余物，奇怪的是地上角落还摆了些铁铲，孔明灯之类的物事。]],["id"]=[[fb30_62]],["item1"]=[[fb30item24]],["name"]=[[司徒堂]],["permission"]=2,["role1"]=[[fb30r62_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb30_58]]}}00000000000